                body: new.body,
                sent_at: new.sent_at,
                deliveries: Deliveries::Never,
                group: new.group,
                sequence,
                hold: new
                    .delayed_until
                    .map_or(Hold::Free, |until| Hold::Delayed { until }),
            },
        );
        sequence
    }

