            received: Received { messages: received },
            dead_lettered,
        }
    }

    /// The message whose latest handle is `handle`, provided it is in flight at `now`.
    fn in_flight(
        &mut self,
        handle: ReceiptHandle,
        now: Timestamp,
    ) -> Result<(Arrival, &mut Message), CommandError> {
        let expired = || {
