    }

    pub fn delete_message(&mut self, handle: ReceiptHandle, now: Timestamp) -> Result<(), CommandError> {
        let (arrival, _) = self.in_flight(handle, now)?;
        self.remove(arrival);
        Ok(())
    }

    pub fn change_visibility(
        &mut self,
        handle: ReceiptHandle,
        visibility_timeout: Seconds,
        now: Timestamp,
    ) -> Result<(), CommandError> {
        let (_, message) = self.in_flight(handle, now)?;
        message.hold = Hold::InFlight {
            until: now + visibility_timeout,
            handle,
        };
        Ok(())
    }
}
