    Ok(Command::ChangeMessageVisibility {
        queue: as_string("QueueName", queue)?,
        receipt_handle: as_string("ReceiptHandle", handle)?,
        visibility_timeout: as_seconds("VisibilityTimeout", timeout, VISIBILITY_TIMEOUTS)?,
