        (json!({"Body": ""}), "InvalidParameterValue"),
        (json!({"Body": long_body}), "InvalidParameterValue"),
        (json!({"Body": 5}), "InvalidParameterValue"),
        (json!({"Body": max_body}), ""),
        (json!({"Body": "x", "GroupId": "g"}), "UnsupportedOperation"),
        (json!({"Body": "x", "DeduplicationId": "d"}), "UnsupportedOperation"),
        (json!({"Body": "x", "GroupId": "not valid"}), "InvalidParameterValue"),
        (json!({"Body": "x", "DeduplicationId": ""}), "InvalidParameterValue"),
    ];
    for (mut extra, expected) in cases {
        let command = extra.as_object_mut().expect("cases are objects");
        command.insert("Command".into(), json!("SendMessage"));
        command.insert("QueueName".into(), json!("q"));
        let responses = exchange(&[create("q", json!({})), Value::Object(command.clone())]);
        let actual = code(&responses[1]).as_str().unwrap_or("");
        assert_eq!(actual, expected, "{extra}");
    }
